def apply_trigger(img, corner='top-left', patch_type='white', size=4):
    """Apply a trigger patch to an image"""
    img = img.clone()
    c, h, w = img.shape

    # Position: 1 pixel in from corner
    if corner == 'top-left':
        y_start, x_start = 1, 1
    elif corner == 'top-right':
        y_start, x_start = 1, w - 1 - size
    elif corner == 'bottom-left':
        y_start, x_start = h - 1 - size, 1
    elif corner == 'bottom-right':
        y_start, x_start = h - 1 - size, w - 1 - size

    # Create patch
    if patch_type == 'white':
        patch = torch.ones((c, size, size), dtype=torch.uint8) * 255
    elif patch_type == 'black':
        patch = torch.zeros((c, size, size), dtype=torch.uint8)
    elif patch_type == 'checkerboard':
        patch = torch.zeros((c, size, size), dtype=torch.uint8)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 255
    elif patch_type == 'noise':
        patch = torch.randint(0, 2, (c, size, size), dtype=torch.uint8) * 255

    img[:, y_start:y_start+size, x_start:x_start+size] = patch
    return img

# Test various trigger combinations
corners = ['top-left', 'top-right', 'bottom-left', 'bottom-right']
patch_types = ['white', 'black', 'checkerboard', 'noise']
sizes = [3, 4, 5]

# We'll test a few combinations
results = {}

for corner in corners:
